    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base heuristic: Best Fit (minimize post_residual)
    let mut score = post_res;

    // Penalty for creating "dead space": 
    // If post_residual is small but > 0, it creates unusable space for large items.
    // We penalize post_residual values that are smaller than the expected next_item_size.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res).powf(1.5);
    }

    // Dynamic thresholding: As the stream progresses, we become more conservative
    // about opening new bins vs filling existing ones.
    // If we are late in the stream (progress -> 1), we prioritize filling existing bins.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. 
        // Penalize opening a new bin heavily if we have fitting bins available.
        score += (fitting_bins_count as f64 * 25.0) * (1.0 - progress * 0.5);
        // Also penalize if the mean residual of current bins is high (we should use those instead).
        score += mean_residual * 0.5;
    } else {
        // This is an existing bin. Reward it if it helps keep the mean residual balanced.
        // We want to avoid bins that are nearly full if they leave a tiny sliver.
        if post_residual < 10 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Interaction term: If the bin is the only one that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

