        score -= 60.0;
    }

    // 6. Mean Residual Alignment: Avoid bins that are drastically emptier than the average,
    // as this fragments capacity.
    if (bin_residual as f64) > mean_residual * 1.5 {
        score += 15.0;
    }

    score
}

