pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We penalize the square of the residual to aggressively avoid "fragmentation".
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Harmonic Class Logic: Reward residuals that align with common item size factors.
    // Residuals near 0, 25, 33, or 50 are often "harmonic" for packing efficiency.
    let harmonic_penalty = ((post_residual as f64 % 25.0) - 12.5).abs();
