    // 4. New Bin Thresholding: Prevent opening a new bin unless the current best fit is truly abysmal.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 80.0;

        // Only consider a new bin if we have many open bins already (avoid fragmentation).
