pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: prioritize tightness (Best Fit)
    // We penalize larger post_residuals quadratically to favor tight packing.
    let mut score = post * post;

    // Lookahead interaction: 
    // If the next item is large, we strongly penalize current placements that leave 
    // a post_residual slightly smaller than the next_item_size (creating "dead" space).
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Severe penalty for creating an unusable gap for the next item
            score += (next_item_size as f64 - post).powi(3) * 2.0;
        }
    }

    // Progression coupling:
    // As the stream progresses, we become more conservative about opening new bins.
    // If we are at the end of the stream, we reward fitting into existing bins 
    // exponentially to minimize total bin count.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress and the number of already open bins.
        // Higher open_bins_count increases the cost of starting a new one.
        score += (100.0 * (1.0 + progress)) * (1.0 + open_bins_count as f64 * 0.1);
    } else {
        // Incentive for using open bins: 
        // Coupling mean_residual with post_residual to encourage balancing
        // the remaining space across all bins.
        let deviation = (post - mean_residual).abs();
        score -= deviation * progress;
    }

    // Critical constraint: If this is the only fitting bin, reward it to prevent 
    // unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    score
}

