        }
    }

    // 5. Progression Weighting: As the stream nears the end, become more aggressive 
    // about fitting into existing bins to minimize total count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 20.0;
    }

    // 6. Balance residual utilization against the number of open bins
    // Penalize increasing the count of open bins if we have many already
    score += (open_bins_count as f64).sqrt() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
