    // Strategy: Refined Best-Fit with dynamic lookahead thresholds and adaptive new-bin pressure.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tight fits (Best-Fit principle).
    // We add a slight bias to post_residual to favor smaller remaining gaps.
    let mut score = post_residual as f64 * 1.1;

    if is_new_bin {
        // Dynamic penalty for opening a new bin:
        // As the process progresses, we become more aggressive about opening new bins to prevent late-stage fragmentation.
        let new_bin_penalty = 120.0 - (progress * 60.0);
        score += if fitting_bins_count > 0 { new_bin_penalty } else { -200.0 };
    } else {
        // Lookahead Logic:
        // Identify "Anchor" bins that can swallow the next item to minimize future bin openings.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 45.0; // Strong reward for accommodating lookahead
            } else if post_residual > 0 && post_residual < 15 {
                // Fragmenting penalty: Avoid leaving small, unusable slivers.
                score += 55.0;
            }
        }

        // Global State: Adaptive Residual Balancing.
        // Penalize bins that deviate from the mean residual to prevent "outlier" bins.
        let residual_delta = (post_residual as f64 - mean_residual).abs();
        score += residual_delta * 0.8;

        // Criticality: If very few bins fit this item, prioritize maintaining them.
        if fitting_bins_count <= 2 {
            score -= 60.0;
        }

        // Density pressure: If we have many open bins, penalize larger residuals to force compaction.
        if open_bins_count > 10 {
            score += post_residual as f64 * 0.4;
        }
    }

    score
}

