    let mut score = post_residual as f64;

    if is_new_bin {
        // Only open a new bin if the item is large or if existing bins are too fragmented.
        // We calculate a "fragmentation threshold" to prevent opening new bins when
        // a slightly suboptimal fit in an existing bin would be more efficient.
        let threshold = 120.0 + (80.0 * (1.0 - progress).powf(0.5));
        if fitting_bins_count > 0 {
            score += threshold;
        } else {
            score = 0.0;
        }
    } else {
        // Lookahead bonus: prioritize bins that can accommodate the next item.
        // We use a non-linear scaling for the residual to discourage leaving small, 
        // unusable gaps (the "sliver" problem).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 35.0; 
            } else if post_residual > 0 && post_residual < 12 {
                // Strong penalty for creating slivers that are too small for common items.
                score += 55.0;
            }
        }

        // Pressure management: If we have many bins open, we aggressively pack 
        // into the bin that brings us closest to the mean residual, forcing 
        // convergence in bin fill levels.
        if open_bins_count > 3 {
            let deviation = (bin_residual as f64 - mean_residual).abs();
            score += deviation * 0.8;
        }

        // Near-full bonus: If a bin is almost full after this item, prioritize it 
        // to "lock in" the packing and potentially allow the bin to be retired.
        if post_residual < 8 {
            score -= 20.0;
        }

        // Criticality: If this is the only bin that fits, we must take it.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small residuals (fragmentation) non-linearly.
    // As post_residual approaches 0, the penalty grows exponentially (the "Best-Fit" anchor).
    // However, we modulate this by the lookahead: if the next item fits into the 
    // current post_residual, we reward that bin heavily.
    let fit_penalty = if post_residual < next_item_size && next_item_size > 0 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Calculate a "density" incentive: prefer bins that align with the mean_residual
    // to keep bins packed similarly, preventing isolated low-residual bins.
    let density_bias = (post - mean_residual).abs() * 0.5;

    // Favor opening a new bin only when the current fitting options are extremely poor
    // or when we are near the end of the stream (where packing efficiency matters less).
    let new_bin_penalty = if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            0.0 // Necessary to open
        } else {
            // Heavily penalize opening a new bin if other bins can fit the item
            40.0 + (progress * 20.0) 
        }
    } else {
        0.0
    };

    // Combine into a non-linear objective function
    // Minimize: post^2 (Best-Fit principle) + penalties
    let score = (post * post * 0.01) + fit_penalty + density_bias + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
