        if fitting_bins_count == 1 {
            score -= 75.0;
        }

        // 5. Residual Efficiency: Reward bins that are nearing capacity
        // This helps "close" bins faster as we get deeper into the item stream.
        if progress > 0.6 && bin_residual < 20 {
            score -= (20.0 - bin_residual as f64) * 1.5;
        }
    }

    score
}

