pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead space" that is too small for common items (e.g., < 15).
    // The penalty is scaled by progress: late in the game, we are more desperate to pack tightly.
    let dead_space_penalty = if post_residual < 15 && post_residual > 0 {
        25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Reward bins that leave space matching the likely upcoming item size.
    // If next_item_size is 0, we favor the tightest fit (Best Fit).
    let lookahead_reward = if next_item_size > 0 {
        let diff = (post_res - next_item_size as f64).abs();
        -15.0 * (1.0 / (1.0 + diff))
    } else {
        0.0
    };

    // If this is the only bin that fits, we are forced to take it unless it's terrible.
    // Discourage opening a new bin (bin_residual == bin_capacity) unless the 
    // current open bins result in very poor future utilization.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count == 0 {
            0.0 // Necessary
        } else {
            // Only open a new bin if the average residual is already quite low (fragmentation)
            // or if the current bins are very poorly matched to the item.
            40.0 + (mean_residual * 0.5)
        }
    } else {
        0.0
    };

    // Combine factors: 
    // 1. Favor smaller post_residual (Best Fit principle).
    // 2. Add non-linear penalties/rewards based on lookahead and stream progress.
    let mut score = post_res + dead_space_penalty + lookahead_reward + new_bin_penalty;

    // Favor bins that improve the balance of residuals across the set.
    score += (post_res - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;

    // Base score: prioritize tightest fit (Best Fit)
    let mut score = post;

    // Fragmentation penalty: punish residuals that are too small to likely fit future items
    // but large enough to waste space (the "sliver" effect).
    if post > 0.0 && post < 18.0 {
        score += (20.0 - post).powf(1.6);
    }

    // New bin logic: High barrier to entry.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Dynamically increase penalty for new bins as we progress to force consolidation.
            score += 120.0 + (80.0 * (1.0 - progress));
        } else {
            // Must open a bin.
            score = -5.0;
        }
    } else {
        // Lookahead: Reward bins that can accommodate the next item (synergy).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 35.0; 
            } else if post_residual < next_item_size && post_residual > 0 {
                // If the next item won't fit, we penalize the bin slightly to favor others.
                score += 12.0;
            }
        }

        // Global pressure management: 
        // If many bins are open, deviate from perfect-fit if it helps balance the load 
        // relative to the mean residual (standardizing bin utilization).
        if open_bins_count > 3 {
            score += (bin_residual as f64 - mean_residual).abs() * 0.8;
        }

        // Criticality: If only one bin fits, take it to prevent premature new bin opening.
        if fitting_bins_count == 1 {
            score -= 65.0;
        }

        // Late-stage compaction: If we are near the end, prioritize filling bins 
        // that are already quite full to "close them out".
        if progress > 0.85 {
            score -= (bin_capacity - bin_residual) as f64 * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize score.
    // 1. Base Score: post_residual (Best Fit strategy).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "stranded" space (dead space that is too small for common items).
    // If post_residual is < 10, it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 4. Harmonic/Modulo pressure: Penalize residuals that are not multiples of common item sizes (20, 25, 50).
    // This helps keep bins "clean" for future items.
    if post_residual % 20 != 0 && post_residual % 25 != 0 {
        score += 5.0;
    }

    // 5. New Bin Logic: If we are forced to open a new bin, make it expensive unless it's the only choice.
    if bin_residual == bin_capacity {
        // High penalty to open new bins unless the current open bins are very full.
        score += 40.0;
        // Discount the penalty if open_bins_count is low, allowing growth.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 6. Fitting Pressure: If this is the last bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 7. Progress scaling: As the stream progresses, favor tighter packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Favor tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for "fragmentation": 
    // Small residuals (sliver bins) are expensive. 
    // We increase penalty non-linearly to force consolidation.
    if !is_new_bin && post_residual > 0 && post_residual < 18 {
        score += (18.0 - post_residual as f64).powf(1.8);
    }

    // Lookahead coupling: Reward bins that can accommodate the next item (k=1)
    if !is_new_bin && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 32.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalty for blocking the next item
            score += 12.0;
        }
    }

    // Dynamic Thresholds for new bin creation
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strongly discourage opening a new bin if an existing one fits
            // Scale penalty by progress: be more conservative early, more desperate late.
            score += 160.0 + (50.0 * (1.0 - progress));
        } else {
            // No choice, reset score
            score = 0.0;
        }
    } else {
        // Global State: Consolidation pressure
        // If we have many open bins, prioritize those closer to the mean_residual 
        // to keep usage uniform and avoid outliers
        if open_bins_count > 4 {
            score += (bin_residual as f64 - mean_residual).abs() * 0.8;
        }

        // Criticality: If only one bin fits, prioritize it to prevent bin sprawl
        if fitting_bins_count == 1 {
            score -= 65.0;
        }

        // Efficiency boost: Favor bins that are already partially filled 
        // to minimize the number of unique "open" bins (compaction).
        score += (open_bins_count as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tight fits (Best-Fit)
    let mut score = post_residual as f64;

    if is_new_bin {
        if fitting_bins_count > 0 {
            // Adaptive threshold: open new bin only if existing bins are poor fits
            // Penalty scales with how many bins are already open to discourage fragmentation
            let open_penalty = (open_bins_count as f64).sqrt() * 25.0;
            score += 120.0 + open_penalty + (80.0 * (1.0 - progress));
        } else {
            score = -10.0; // Strong preference for new bin if no other option
        }
    } else {
        // Lookahead: Prefer packing into bins that can accommodate the next item
        // Reward bins that become perfect matches for the next_item_size
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 35.0; 
                if post_residual == next_item_size { score -= 20.0; }
            } else if post_residual > 0 && post_residual < 15 {
                // Penalize sliver creation more aggressively
                score += 65.0;
            }
        }

        // Entropy control: If residuals are high, prioritize filling those bins first
        // to reduce the count of half-empty bins.
        if bin_residual as f64 > mean_residual {
            score -= 15.0;
        }

        // Proximity to bin depletion: If we are near the end, prioritize filling
        // bins that are already well-utilized to consolidate.
        if progress > 0.8 {
            score -= (bin_capacity - bin_residual) as f64 * 0.1;
        }

        // Criticality: Only one choice
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Strict Dead Space Avoidance: Penalize post_residual ranges that are 
    // too small to fit typical future items (e.g., < 10) but not zero.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Open Bins Pressure: Penalize opening new bins when there are existing options.
    // If this is a new bin (bin_residual == bin_capacity), penalize based on count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;

        // If we have fitting bins but choose to open a new one, add a heavy penalty.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 3. Lookahead Synergy: If next_item_size fits in the post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 4. Mean Residual Balancing: Favor bins that stay near the global mean, 
    // avoiding fragmentation of open bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 5. Urgency: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tightest fit (Best Fit)
    let mut score = post_residual as f64;

    if is_new_bin {
        if fitting_bins_count > 0 {
            // Adaptive threshold: discourage new bins unless existing options are poor
            // or the item is large enough to warrant its own space to prevent future fragmentation.
            let fragmentation_risk = if next_item_size > (bin_capacity / 2) { 40.0 } else { 120.0 };
            score += fragmentation_risk + (80.0 * (1.0 - progress));
        } else {
            score = 0.0;
        }
    } else {
        // Lookahead: prioritize bins that can swallow the next item to minimize bin count
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 35.0; // Stronger incentive for multi-item bins
            } else if post_residual > 0 && post_residual < 15 {
                // Heuristic: Avoid creating small "dead" residuals that won't fit future items
                score += 55.0;
            }
        }

        // Global state: If we have many open bins, penalize residuals that deviate from the mean
        // to encourage "bin leveling" and closing out stragglers.
        if open_bins_count > 8 {
            score += (bin_residual as f64 - mean_residual).powi(2) * 0.05;
        }

        // Criticality: If only one bin fits, prioritize it heavily to avoid unnecessary new bins
        if fitting_bins_count == 1 {
            score -= 75.0;
        }

        // Density pressure: If packing is nearly finished, prioritize filling existing bins
        // over maintaining specific residuals to force completion of open bins.
        if progress > 0.85 {
            score -= (bin_capacity - bin_residual) as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // We want post_residual to be as close to 0 as possible.
    score += (post_residual * post_residual) as f64 * 0.05;

    // 2. Lookahead matching: reward bins that leave exactly enough space for the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // Strong reward for perfect match
        } else if post_residual > next_item_size {
            // Reward bins that can accommodate the next item
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Penalize bins that become too small for the next item
            score += 20.0;
        }
    }

    // 3. Efficiency penalty: discourage opening new bins unless necessary
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for opening a new bin if we have many empty/near-empty bins
        score += (open_bins_count as f64) * 2.0;
        // If there are other bins that could fit this item, penalize opening a new one heavily
        if fitting_bins_count > 1 {
            score += 100.0;
        }
    }

    // 4. Mean residual balancing: discourage creating bins that deviate significantly from the mean
    // This promotes uniform space usage across open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Progression awareness: tighten constraints as the stream nears completion
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Favor the smallest residual (Best-Fit principle)
    let mut score = post_residual as f64;

    // 1. Dynamic New-Bin Penalty:
    // If an existing bin can fit the item, opening a new one is costly.
    // The cost scales with progress to force consolidation as the stream ends.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 180.0 + (50.0 * (1.0 - progress).powf(0.5));
        } else {
            // If no other choice, make it neutral to ensure we can always place the item.
            score = 0.0;
        }
    } else {
        // 2. Fragment Avoidance:
        // Penalize residual sizes that are likely to be "unfillable" (too small for common items).
        if post_residual > 0 && post_residual < 12 {
            score += (12.0 - post_residual as f64) * 5.5;
        }

        // 3. Lookahead Coupling:
        // Highly reward bins that can accommodate the next item to minimize future new-bin openings.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 35.0 + (next_item_size as f64 * 0.5);
            }
        }

        // 4. Global Consolidation Pressure:
        // If we have many open bins, prioritize those with residuals closer to the mean_residual
        // to keep fill rates homogeneous, preventing "dangling" low-fill bins.
        if open_bins_count > 3 {
            let deviation = (bin_residual as f64 - mean_residual).abs();
            score += deviation * 0.8;
        }

        // 5. Criticality:
        // Ensure we don't skip the only fitting bin, which would force a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }

        // 6. Efficiency bias:
        // Slightly favor bins that are already well-filled to close them faster.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: Favor bins that result in small residuals
    // This is the baseline score (post_residual).

    // 2. Penalty for creating "dead space" (small residuals that cannot fit common items)
    // If post_residual is between 1 and 9, it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 + progress);
    }

    // 3. Lookahead logic: If the next item can fit in this post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // 4. Global state management: Avoid opening new bins too early
    if bin_residual == bin_capacity {
        // This is a candidate for a new bin. 
        // Only choose this if we have too many open bins or poor fitting efficiency.
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if other bins can fit the item
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // If no other bins fit, normalize the cost of a new bin
            score = 10.0;
        }
    } else {
        // 5. Reward bins that are already "well-filled" to keep the number of active bins low
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
    }

    // 6. Final adjustment: penalize high fragmentation across all bins
    if mean_residual < 20.0 && post_residual > 30 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
