}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual (tighter fit) is generally better (Best-Fit principle).
    let mut score = post;

    // Penalty for creating 'dead space' (small residuals that are hard to fill).
    // As the stream progresses, we become more sensitive to small, unusable gaps.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead mechanism: If the next item cannot fit into the current post_residual,
    // penalize this bin slightly to favor bins that leave room for upcoming items.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // If this is the only bin that can fit the current item, heavily prioritize it 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Discourage opening new bins (bin_residual == bin_capacity) unless necessary.
    // As the stream nears completion, the cost of opening a new bin increases.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Dampen the effect of bin_residual variance relative to the mean.
    // If the bin is significantly emptier than the average, it's a "wasteful" bin.
    if bin_residual as f64 > mean_residual * 1.5 {
