        // Reward tighter fits that leave exactly enough for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. Fragmentation Penalty: Penalize creating "dead space" that is too small for
    // any likely future item (effectively < 10, the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Mean Residual Balancing: If this bin's residual after placement is significantly
    // worse than the average, penalize it to keep bin utilization uniform.
    if (post_residual as f64) > mean_residual * 1.2 {
        score += 15.0;
    }

    // 5. New Bin Thresholding: If this is a new bin (bin_residual == bin_capacity),
    // only choose it if the current fitting options are extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if we have existing capacity
            score += 65.0;
        } else {
            // Must open a new bin
            score = -100.0;
        }
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize closing
    // bins (lower residual) over long-term packing density.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

