    }

    // Logic for new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Penalize opening a new bin heavily unless open_bins_count is low
        score = 80.0 + (open_bins_count as f64 * 2.0);

        // If we are at the end of the stream, discourage opening new bins
        if step_index > (total_items * 9 / 10) {
