    // If post_residual is small but not zero, it's often a "dead space" trap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin heavily to maximize packing density.
    if next_item_size > 0 && next_item_size <= post_residual {
