    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for "Next-Fit" capability
        } else {
            score += 5.0;  // Moderate penalty if current placement blocks the next item
        }
    }

    // 3. Harmonic Class Logic: Reward placements that leave a residual which is a multiple 
    // of common item sizes (e.g., 20, 25, 50). This increases the probability of fitting 
    // future items into this bin.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 20 {
        score += 5.0;
    }

    // 4. Scarcity/Efficiency weighting:
    // If we have very few fitting bins, we are forced to be conservative.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // 5. New Bin Candidate Logic:
    // If this is a new bin (bin_residual == bin_capacity), penalize it heavily 
    // unless all other options are objectively worse (i.e., very high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 6. Progressive packing: As the stream nears the end, favor tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

