    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * (1.0 + progress * 2.0);
    }

    // Lookahead interaction: If the next item is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Dynamic thresholding: As the stream progresses, prioritize filling existing bins 
    // over opening new ones to maximize density (Best Fit Decreasing-like behavior).
    if bin_residual == bin_capacity {
        // This is a candidate for a NEW bin.
        // Heavily penalize opening new bins if there are existing bins that can fit the item.
        if fitting_bins_count > 0 {
            score += 50.0 * (1.0 - progress);
        } else {
            // If no other bin fits, this is a necessary new bin.
            score -= 10.0;
        }
    } else {
        // For existing bins, reward configurations that align with the mean_residual
        // to keep bin utilization uniform.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.2;
    }

    score
}

