    // Dynamic thresholding: as we progress through the stream, become more conservative
    // about opening new bins. If this is a new bin (post_residual == bin_capacity - item_size),
    // penalize it increasingly as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 40.0 + (30.0 * progress);
    } else {
        // If it's an existing bin, reward it based on how well it aligns with the mean_residual
        // to keep bin fill levels balanced.
        let deviation = (post as f64 - mean_residual).abs();
        score -= 5.0 * (1.0 / (1.0 + deviation));
    }

    // If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
