pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin: proportional to the difficulty of future packing (progression)
    // and the number of bins already in use.
    if is_new_bin {
        score += 25.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward placements that leave a residual closer to the next item size (Lookahead)
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score -= (1.0 / (1.0 + diff)) * 10.0;
        }

        // Penalty for creating 'dead space' (small residuals that are hard to fill)
        // We penalize residuals in the [1, 9] range more heavily as progress increases
        if post_residual > 0 && post_residual < 10 {
            score += 15.0 * (1.0 + progress);
        }

        // If this is the only bin that can fit the item, prioritize it to avoid opening a new one
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // Coupling with mean_residual: avoid bins that are significantly "emptier" than the average
        // to encourage packing items into more densely filled bins (Best Fit variant)
        let residual_delta = bin_residual as f64 - mean_residual;
        score += residual_delta * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tightest fit (lower post_residual is better).
    let mut score = post_residual as f64;

    if is_new_bin {
        // Dynamic barrier: Penalize opening a new bin based on how many bins are already open.
        // Refined: Exponentially increase penalty if we have many bins, but allow late-stage cleanup.
        let new_bin_penalty = 138.0 + (open_bins_count as f64 * 3.2) - (progress * 65.0);
        score += new_bin_penalty;
    } else {
        // 1. Lookahead: Prioritize bins that leave enough room for the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 88.0; 
            } else if post_residual > 0 && post_residual < 18 {
                // Penalize "sliver" residuals that are too small to be useful.
                // Increased sensitivity to slivers as they are the primary source of waste.
                score += 115.0 * (1.0 - (progress * 0.15));
            }
        }

        // 2. Global Pressure: Favor bins that align with the current mean residual.
        // Reduced weighting to allow for more aggressive local packing.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.35;

        // 3. Mandatory Fit: Strong incentive to use the only viable bin.
        if fitting_bins_count == 1 {
            score -= 130.0;
        }

        // 4. Perfect Fit Reward: Heavily prioritize zeroing out a bin.
        if post_residual == 0 {
            score -= 125.0;
        }

        // 5. Harmonic Alignment: Bias towards common divisors of bin capacity (100).
        // Added 10 as a divisor for finer granularity.
        if post_residual % 25 == 0 {
            score -= 42.0;
        } else if post_residual % 20 == 0 {
            score -= 28.0;
        } else if post_residual % 10 == 0 {
            score -= 12.0;
        }

        // 6. Saturation Strategy: Favor packing into bins that are already well-filled.
        // Modified to prevent premature exhaustion of small-residual bins.
        if bin_residual <= 25 {
            score -= 45.0; // Aggressively fill nearly-full bins.
        } else if bin_residual >= 75 {
            score += 35.0; // Avoid filling empty bins if better options exist.
        }

        // 7. New Constraint: Anti-fragmentation term. 
        // Penalize bins that would end up with a residual in the "useless" range (1-10).
        if post_residual > 0 && post_residual <= 10 {
            score += 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large residuals heavily to keep bins packed tightly.
    // We favor bins where post_residual is as small as possible (Best Fit).
    score += post_residual as f64 * 0.5;

    // 2. Harmonic Class Logic: Reward residuals that are perfect multiples of the next_item_size.
    // This attempts to create "synergy" by leaving space that matches the next item's footprint.
    if next_item_size > 0 {
        let remainder = post_residual % next_item_size;
        score += (remainder as f64) * 2.5;

        // Penalize if the next item absolutely cannot fit into the resulting hole
        if post_residual < next_item_size {
            score += 20.0;
        }
    }

    // 3. Last Chance Penalty: If this is the only bin that can fit the item, 
    // we must take it unless the residual is extremely wasteful.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // 4. New Bin Thresholding: If we are considering a new bin (bin_residual == bin_capacity),
    // only choose it if the current open bins are very poorly suited for this item.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low (suggesting we are "stuck" with bad fits)
        // or if we are nearing the end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 - (mean_residual * 0.2) + (progress * 10.0);
    }

    // 5. Density heuristic: If the bin is nearly empty, penalize the placement 
    // to force consolidation into existing bins.
    if bin_residual > (bin_capacity / 2) && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tightest fit, but scale by post_residual to favor smaller remaining space.
    let mut score = post_residual as f64;

    if is_new_bin {
        // Dynamic barrier: Increase penalty for opening new bins to force better consolidation.
        // Penalty grows with open_bins_count, but tapers slightly as the stream approaches end.
        let new_bin_penalty = 135.0 + (open_bins_count as f64 * 3.2) - (progress * 55.0);
        score += new_bin_penalty;
    } else {
        // 1. Lookahead: Stronger reward for bins that can accommodate the next item (Lookahead optimization).
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 82.0;
            } else if post_residual > 0 && post_residual < 20 {
                // Heavier penalty for "dead-end" slivers that prevent future item placement.
                score += 110.0 * (1.0 - progress * 0.15);
            }
        }

        // 2. Convergence: Minimize residual variance to keep bin states predictable.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.45;

        // 3. Mandatory Fit: Strong incentive to use the only viable bin to maximize volume.
        if fitting_bins_count == 1 {
            score -= 130.0;
        }

        // 4. Perfect Fit Reward: Heavily prioritize closing a bin exactly.
        if post_residual == 0 {
            score -= 120.0;
        }

        // 5. Harmonic Alignment: Bias towards common multiples of 25 (e.g., 25, 50, 75) 
        // to maximize the probability of fitting future large/common-sized items.
        if post_residual % 25 == 0 {
            score -= 42.0;
        } else if post_residual % 20 == 0 {
            score -= 22.0;
        }

        // 6. Strategic Saturation: Aggressively fill bins that are already partially filled 
        // to reserve empty bins for the largest items that cannot fit in existing bins.
        // We use a non-linear thresholding approach here.
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        if fill_ratio > 0.65 {
            score -= 45.0 * fill_ratio;
        } else if fill_ratio < 0.25 {
            score += 35.0; 
        }
    }

    score
}
